SELECT tracking_process_id, request_tracking_id, tracking_process_identifier, tracking_process_type, federated_twin_id, federated_digital_object_id, digital_twin_id, digital_object_id, tracking_command, tracking_kafka_group, tracking_kafka_topic, data_filter_type, event_occurred_count, event_condition, event_delay, event_end_date, tracking_status, create_time, tracking_status_change_time FROM tracking_process_info WHERE 1=1
AND tracking_process_id = #{trackingProcessId}
AND request_tracking_id = #{requestTrackingId}
ORDER BY tracking_process_id
LIMIT #{start},#{end}

